return items.map((item, index) => {
  const product = item.json.result?.product ?? {};
  return {
    json: {
      asin: product.asin ?? item.json.request_parameters?.asin ?? null,
      title: product.title ?? null,
      category_rank: product.bestseller?.category_rank ?? product.bestseller?.rank ?? null,
      category_title: product.bestseller?.category_title ?? product.bestseller?.context_name ?? null,
      image: product.image?.link ?? product.media?.image_url ?? null,
      operation_version: item.json.request_parameters?.operation_version ?? null,
    },
    pairedItem: { item: index },
  };
});
